parameters.jsCode:
// Extract text from Anthropic response + carry over sheet row metadata
const aiResp = $input.first().json;
const sheetRow = $('Read calendario (today, pronto)').first().json;

const postText = aiResp.content?.[0]?.text || '';

// Generate HMAC token for approval links (replace SECRET with n8n env var)
const crypto = require('crypto');
const secret = $env.APPROVAL_SECRET || 'CHANGE_ME_in_n8n_env';
const payload = `${sheetRow.data}-${sheetRow.target}-${Date.now()}`;
const token = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 16);

return [{
  json: {
    ...sheetRow,
    postText,
    approvalToken: token,
    rowIndex: sheetRow.row_number || 0,
  }
}];

